import { skillBySlug } from "./catalog";

const HEADER = `#!/usr/bin/env bash
# Generated by Helix Skill Creator — review before running.
set -euo pipefail

log() { printf '%s %s\\n' "$(date -Iseconds)" "$*"; }
need() { command -v "$1" >/dev/null 2>&1 || { log "missing dependency: $1"; exit 1; }; }
`;

export function fallbackLinuxScript(input: {
  name: string;
  brief: string;
  target: string;
  slugs: string[];
}): string {
  const skills = input.slugs
    .map((s) => skillBySlug(s)?.name ?? s)
    .join(", ");
  const body = scriptBody(input.target, input.brief);
  return `${HEADER}
# Skill: ${input.name}
# Brief: ${input.brief.replace(/\n/g, " ").slice(0, 240)}
# Skills: ${skills || "none"}
# Target: ${input.target}

${body}
`;
}

function scriptBody(target: string, brief: string): string {
  switch (target) {
    case "hardening":
      return `# Android / host hardening snapshot (read-only by default)
need adb || true
OUT="\${HELIX_OUT:-$HOME/.local/share/helix/android-hardening}"
mkdir -p "$OUT"
log "writing snapshot to $OUT"

if command -v adb >/dev/null 2>&1; then
  adb start-server >/dev/null
  adb devices -l > "$OUT/devices.txt" || true
  adb shell getprop ro.crypto.state > "$OUT/crypto-state.txt" 2>/dev/null || true
  adb shell settings get global development_settings_enabled > "$OUT/dev-options.txt" 2>/dev/null || true
  adb shell settings get global package_verifier_enable > "$OUT/play-protect.txt" 2>/dev/null || true
  log "device snapshot captured (no settings mutated)"
else
  log "adb not installed — host-only checks"
fi

umask 077
printf 'usb authorized computers should be reviewed in developer options\\n' > "$OUT/reminders.txt"
log "done. compact this folder into Helix memory with tag android"
`;
    case "systemd":
      return `UNIT_DIR="\${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user"
mkdir -p "$UNIT_DIR"
UNIT="$UNIT_DIR/helix-daily-report.service"
TIMER="$UNIT_DIR/helix-daily-report.timer"

cat > "$UNIT" <<'EOF'
[Unit]
Description=Helix daily tutor report hook

[Service]
Type=oneshot
ExecStart=/usr/bin/true
# Replace with: helix report --out %h/.local/share/helix/report.txt
EOF

cat > "$TIMER" <<'EOF'
[Unit]
Description=Run Helix daily report each morning

[Timer]
OnCalendar=*-*-* 08:00:00
Persistent=true

[Install]
WantedBy=timers.target
EOF

log "wrote $UNIT and $TIMER"
log "enable with: systemctl --user daemon-reload && systemctl --user enable --now helix-daily-report.timer"
`;
    case "audit":
      return `LOG_DIR="\${HELIX_AUDIT:-$HOME/.local/share/helix/audit}"
mkdir -p "$LOG_DIR"
chmod 700 "$LOG_DIR"
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
FILE="$LOG_DIR/$STAMP.log"
{
  echo "event=operator-action"
  echo "host=$(hostname)"
  echo "user=\${USER:-unknown}"
  echo "brief=$(printf '%s' '${shellEscape(brief.slice(0, 180))}')"
} > "$FILE"
chmod 600 "$FILE"
log "audit line written to $FILE"
`;
    case "loop":
      return `LOOP_DIR="\${HELIX_LOOPS:-$HOME/.local/share/helix/loops}"
UNIT_DIR="\${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user"
mkdir -p "$LOOP_DIR" "$UNIT_DIR"
chmod 700 "$LOOP_DIR"

# The timer runs this file. It records a trace and writes a proposal.
# It never edits a skill.
cat > "$LOOP_DIR/review.sh" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
LOOP_DIR="\${HELIX_LOOPS:-$HOME/.local/share/helix/loops}"
mkdir -p "$LOOP_DIR"
TRACE="$LOOP_DIR/traces.jsonl"
PROPOSAL="$LOOP_DIR/proposal.md"
touch "$TRACE"
chmod 600 "$TRACE"
STAMP="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
printf '{"at":"%s","skill":"agent-loop-improver","note":"observer pass; do not apply"}\\n' "$STAMP" >> "$TRACE"
{
  echo "# Loop proposal"
  echo
  echo "Generated $STAMP. Proposal only. Do not install this automatically."
  echo
  echo "One skill. One edit. A person merges it."
  echo
  echo "## Recent traces"
  echo
  tail -n 20 "$TRACE"
  echo
  echo "## Suggested edit"
  echo "Name the skill that should have stopped the repeated mistake."
  echo "Add one step, gate, or anti-pattern. Leave governance and the token budget alone."
} > "$PROPOSAL"
chmod 600 "$PROPOSAL"
printf '%s proposal %s\\n' "$(date -Iseconds)" "$PROPOSAL"
EOF
chmod 700 "$LOOP_DIR/review.sh"
"$LOOP_DIR/review.sh"

cat > "$UNIT_DIR/helix-loop-improver.service" <<'EOF'
[Unit]
Description=Helix loop improver (proposal only)

[Service]
Type=oneshot
ExecStart=%h/.local/share/helix/loops/review.sh
EOF

cat > "$UNIT_DIR/helix-loop-improver.timer" <<'EOF'
[Unit]
Description=Weekly Helix loop review

[Timer]
OnCalendar=weekly
Persistent=true

[Install]
WantedBy=timers.target
EOF

log "review script and proposal are in $LOOP_DIR"
log "enable with: systemctl --user daemon-reload && systemctl --user enable --now helix-loop-improver.timer"
log "the timer does not install or overwrite skills"
`;
    default:
      return `WORKDIR="\${HELIX_WORK:-$HOME/.local/share/helix/jobs}"
mkdir -p "$WORKDIR"
cd "$WORKDIR"
log "job start: ${shellEscape(brief.slice(0, 120))}"

# Idempotent placeholder — replace steps after review.
if [[ ! -f .helix-initialized ]]; then
  umask 077
  touch .helix-initialized
  log "workspace marker created"
else
  log "workspace already initialized"
fi

log "job complete"
`;
  }
}

function shellEscape(s: string): string {
  return s.replace(/'/g, "").replace(/"/g, "").replace(/\$/g, "").replace(/`/g, "");
}

export function fallbackProtocol(input: {
  name: string;
  brief: string;
  slugs: string[];
}): string {
  const children = input.slugs
    .map((slug) => skillBySlug(slug))
    .filter((s): s is NonNullable<typeof s> => Boolean(s));
  const inherited = children
    .map((s) => `- ${s.name} (\`${s.slug}\`): ${s.summary}`)
    .join("\n");
  return `# ${input.name}

## Purpose
${input.brief.trim() || "Operator-authored skill."}

## Inherited
${inherited || "- (none — original skill)"}

## Steps
1. Pre-plan tokens with Precision Token Engineering.
2. Check Agent Governance gates before any destructive step.
3. Run the Linux script from a user directory; do not pipe to sh.
4. Record the outcome with \`/log\`. Flag a mistake if it repeats.

## Compact
After a successful run, write a memory note ≤ 200 tokens and compact weekly.

## Out of scope
Attacking systems you do not own. Bypassing locks. Shipping secrets in the script.
`;
}
